  return useCallback((event) => {
    if (!enabled) return

    event.preventDefault()
    openMenu({
      source: MenuOpenSource.DESKTOP,
      anchorX: event.clientX,
      anchorY: event.clientY,
      selectedText: '',
    })
  }, [enabled, openMenu])
}
```

