```javascript
function runMobileSelectionDecision(decision) {
  if (decision.type === MobileSelectionMenuDecisionType.OPEN_MENU) {
    openMenu({
      source: MenuOpenSource.MOBILE_SELECTION,
      ...decision.selection,
    })
    return
  }

  if (decision.type === MobileSelectionMenuDecisionType.CLOSE_MENU) {
    closeMenu()
  }
}
```

